//! 🧪️ Real native template prefixes remain untyped through paid cancellation and exact Work recovery.
use crate::*;
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
use std::{mem::{ManuallyDrop,MaybeUninit,size_of},sync::atomic::{AtomicUsize,Ordering}};
static DROPS:AtomicUsize=AtomicUsize::new(0);
struct Header{body:[u8;8192],empty:Option<String>}
impl Drop for Header{fn drop(&mut self){assert!(self.empty.is_none());DROPS.fetch_add(1,Ordering::SeqCst);}}
unsafe fn template(target:*mut MaybeUninit<Header>,offset:usize,count:usize){const EMPTY:ManuallyDrop<Header>=ManuallyDrop::new(Header{body:[7;8192],empty:None});let source=&EMPTY;unsafe{std::ptr::copy_nonoverlapping((source as*const ManuallyDrop<Header>).cast::<MaybeUninit<u8>>().add(offset),target.cast::<MaybeUninit<u8>>().add(offset),count)}}
unsafe fn other_template(target:*mut MaybeUninit<Header>,offset:usize,count:usize){const EMPTY:ManuallyDrop<Header>=ManuallyDrop::new(Header{body:[9;8192],empty:None});let source=&EMPTY;unsafe{std::ptr::copy_nonoverlapping((source as*const ManuallyDrop<Header>).cast::<MaybeUninit<u8>>().add(offset),target.cast::<MaybeUninit<u8>>().add(offset),count)}}
fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes<=4096);RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn run(bank:&mut EffectBank,g:RetainedCloneGrant,work:u64,operation:impl FnOnce(&mut RetainedAllocationEffect<'_>)->RetainedWorkOutcome)->RetainedWorkOutcome{
 let((poll,actual),heap)=observe(||bank.run(g,work,|effect|RetainedWorkPoll::Complete(operation(effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("native template leaf is synchronous")};let p=turn.result.as_ref().map(|step|step.progress()).unwrap_or_else(|error|error.retained_progress());assert!(p.fits(g));if let Some(actual)=actual{assert_eq!(actual,heap.0)}assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));let _=bank.take_admitted();bank.post(p,g,heap);turn
}
fn complete(poll:RetainedWorkPoll)->RetainedWorkOutcome{match poll{RetainedWorkPoll::Complete(turn)=>turn,RetainedWorkPoll::Pending{..}=>panic!("native leaf remained pending")}}
#[test]fn native_cold_template_has_bounded_prefixes_original_work_and_untyped_cancel(){
 let law:serde_json::Value=serde_json::from_str(include_str!("template.json")).unwrap();DROPS.store(0,Ordering::SeqCst);let native=unsafe{NativeSeedTemplate::new(template)};let foreign_template=unsafe{NativeSeedTemplate::new(other_template)};
 for cut in law["cancellationCuts"].as_array().unwrap(){let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut foreign=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut owner=NativeOwnedStorage::<Header>::empty();let g=grant(NativeOwnedStorage::<Header>::reserve_demand());run(&mut bank,g,1,|effect|complete(owner.reserve_empty(effect))).result.unwrap();let address=owner.address();
  for _ in 0..cut.as_u64().unwrap(){let d=owner.template_seed_demand(native).unwrap();let g=grant(d);let before=owner.seeded_bytes();let denied=run(&mut bank,g,0,|effect|owner.initialize_template(native,effect));assert_eq!(denied.work,0);assert_eq!(owner.seeded_bytes(),before);assert!(owner.get().is_none());run(&mut bank,g,1,|effect|owner.initialize_template(native,effect)).result.unwrap();assert_eq!(owner.address(),address);assert!(!owner.initialized());assert!(owner.get().is_none());assert!(unsafe{owner.uninitialized_ptr()}.is_none());}
  if cut.as_u64().unwrap()!=0{let before=owner.seeded_bytes();let g=grant(owner.template_seed_demand(native).unwrap());let denied=run(&mut foreign,g,1,|effect|owner.initialize_template(native,effect));assert!(denied.result.is_err());assert_eq!(denied.work,0);let denied=run(&mut bank,g,1,|effect|owner.initialize_template(foreign_template,effect));assert!(denied.result.is_err());assert_eq!(denied.work,0);assert_eq!(owner.seeded_bytes(),before);let g=grant(owner.release_demand());let denied=run(&mut foreign,g,1,|effect|owner.release(effect));assert!(denied.result.is_err());assert_eq!(denied.work,0);assert_eq!(owner.address(),address);assert_eq!(owner.seeded_bytes(),before);let mut calls=0;let denied=run(&mut bank,g,1,|effect|complete(owner.initialize_seed(effect,||{calls+=1;Ok(Header{body:[0;8192],empty:None})})));assert!(denied.result.is_err());assert_eq!(denied.work,0);assert_eq!(calls,0);}
  let g=grant(owner.release_demand());run(&mut bank,g,1,|effect|owner.release(effect)).result.unwrap();assert!(owner.terminal_is_empty());assert_eq!(DROPS.load(Ordering::SeqCst),law["partialDestructorCalls"].as_u64().unwrap()as usize);
 }
 let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut owner=NativeOwnedStorage::<Header>::empty();let g=grant(NativeOwnedStorage::<Header>::reserve_demand());run(&mut bank,g,1,|effect|complete(owner.reserve_empty(effect))).result.unwrap();let address=owner.address();for _ in 0..32{if owner.initialized(){break}let g=grant(owner.template_seed_demand(native).unwrap());run(&mut bank,g,1,|effect|owner.initialize_template(native,effect)).result.unwrap();}assert!(owner.initialized());assert_eq!(owner.get().unwrap().body,[7;8192]);assert_eq!(owner.address(),address);let mut output=None;let g=grant(NativeOwnedStorage::<Header>::box_demand());run(&mut bank,g,1,|effect|complete(owner.take_box_into(&mut output,effect))).result.unwrap();assert!(owner.terminal_is_empty());assert_eq!(output.as_ref().unwrap().as_ref()as*const Header as usize,address.unwrap());let d=RetirementDemand{copy_bytes:size_of::<Option<Box<Header>>>(),release_bytes:size_of::<Header>(),depth:1,..Default::default()};run(&mut bank,grant(d),1,|effect|{assert!(effect.performed(1).unwrap());drop(output.take());RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()})),work:1}}).result.unwrap();assert_eq!(DROPS.load(Ordering::SeqCst),law["completeDestructorCalls"].as_u64().unwrap()as usize);
}

static FIELD_DROPS:AtomicUsize=AtomicUsize::new(0);
struct InteriorHeader{flag:AtomicUsize,body:[u8;8192],empty:Option<String>}
impl Drop for InteriorHeader{fn drop(&mut self){assert!(self.empty.is_none());FIELD_DROPS.fetch_add(1,Ordering::SeqCst);}}
unsafe fn field_size(_: *mut MaybeUninit<InteriorHeader>,index:usize)->Option<usize>{match index{0=>Some(size_of::<AtomicUsize>()),1..=8=>Some(1024),9=>Some(size_of::<Option<String>>()),_=>None}}
unsafe fn field_write<const SUBSET:bool>(target:*mut MaybeUninit<InteriorHeader>,index:usize)->bool{let target=target.cast::<InteriorHeader>();unsafe{match index{0=>std::ptr::addr_of_mut!((*target).flag).write(AtomicUsize::new(usize::from(SUBSET))),1..=8=>std::ptr::write_bytes(std::ptr::addr_of_mut!((*target).body).cast::<u8>().add((index-1)*1024),7,1024),9=>std::ptr::addr_of_mut!((*target).empty).write(None),_=>return false}}true}
#[test]fn native_field_seed_handles_interior_mutability_without_a_whole_seed(){
 let law:serde_json::Value=serde_json::from_str(include_str!("template.json")).unwrap();FIELD_DROPS.store(0,Ordering::SeqCst);let native=unsafe{NativeSeedTemplate::fields(10,field_size,field_write::<true>)};let other=unsafe{NativeSeedTemplate::fields(10,field_size,field_write::<false>)};
 for cut in law["fieldPlan"]["cancellationCuts"].as_array().unwrap(){let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut owner=NativeOwnedStorage::<InteriorHeader>::empty();let g=grant(NativeOwnedStorage::<InteriorHeader>::reserve_demand());run(&mut bank,g,1,|effect|complete(owner.reserve_empty(effect))).result.unwrap();for _ in 0..cut.as_u64().unwrap(){let g=grant(owner.template_seed_demand(native).unwrap());run(&mut bank,g,1,|effect|owner.initialize_template(native,effect)).result.unwrap();assert!(owner.get().is_none());assert!(unsafe{owner.uninitialized_ptr()}.is_none());}if cut.as_u64().unwrap()!=0{assert!(owner.template_seed_demand(other).is_err());}let g=grant(owner.release_demand());run(&mut bank,g,1,|effect|owner.release(effect)).result.unwrap();assert!(owner.terminal_is_empty());assert_eq!(FIELD_DROPS.load(Ordering::SeqCst),0);}
 let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut owner=NativeOwnedStorage::<InteriorHeader>::empty();let g=grant(NativeOwnedStorage::<InteriorHeader>::reserve_demand());run(&mut bank,g,1,|effect|complete(owner.reserve_empty(effect))).result.unwrap();for step in 0..law["fieldPlan"]["parts"].as_u64().unwrap(){assert!(owner.get().is_none());let g=grant(owner.template_seed_demand(native).unwrap());let before=owner.seeded_bytes();let denied=run(&mut bank,RetainedCloneGrant{maximum_copy_bytes:0,..g},1,|effect|owner.initialize_template(native,effect));assert_eq!(denied.work,0);assert_eq!(owner.seeded_bytes(),before);let denied=run(&mut bank,g,0,|effect|owner.initialize_template(native,effect));assert_eq!(denied.work,0);assert_eq!(owner.seeded_bytes(),before);run(&mut bank,g,1,|effect|owner.initialize_template(native,effect)).result.unwrap();assert_eq!(owner.initialized(),step+1==law["fieldPlan"]["parts"].as_u64().unwrap());}assert_eq!(owner.get().unwrap().flag.load(Ordering::SeqCst),1);assert_eq!(owner.get().unwrap().body,[7;8192]);let mut output=None;let g=grant(NativeOwnedStorage::<InteriorHeader>::box_demand());run(&mut bank,g,1,|effect|complete(owner.take_box_into(&mut output,effect))).result.unwrap();let d=RetirementDemand{copy_bytes:size_of::<Option<Box<InteriorHeader>>>(),release_bytes:size_of::<InteriorHeader>(),depth:1,..Default::default()};run(&mut bank,grant(d),1,|effect|{assert!(effect.performed(1).unwrap());drop(output.take());RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()})),work:1}}).result.unwrap();assert_eq!(FIELD_DROPS.load(Ordering::SeqCst),1);
}
